<?php
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function url($page,$extra=[]){return 'index.php?'.http_build_query(array_merge(['page'=>$page],$extra));}
function redirect($page,$extra=[]){header('Location: '.url($page,$extra));exit;}
function page_title($p){$titles=['welcome'=>'Find work that moves you forward','signin'=>'Welcome back','signup'=>'Create your account','role'=>'Choose your path','employee-onboarding'=>'Build your profile','employer-onboarding'=>'Set up your company','home'=>'Your workspace','jobs'=>'Explore opportunities','job-detail'=>'Job details','apply'=>'Application submitted','interviews'=>'Interviews','profile'=>'Your profile','edit-profile'=>'Edit profile','notifications'=>'Notifications','settings'=>'Notification preferences','plans'=>'Choose a plan','employer-home'=>'Recruitment workspace','search-candidates'=>'Find talent','post-job'=>'Create a job post','job-preview'=>'Review job post'];return $titles[$p]??'Easy Employment';}
