['id'=>101,'title'=>'Frontend Developer','company'=>'Northstar Digital','location'=>'Ahmedabad, Gujarat','type'=>'Full Time','workplace'=>'Hybrid','salary'=>'₹5–8 LPA','experience'=>'1–3 years','category'=>'Technology','logo'=>'N','color'=>'violet','posted'=>'2 days ago','description'=>'Build polished, accessible web experiences alongside a product-minded engineering team. You will work closely with design and backend colleagues to ship features that customers love.','skills'=>['HTML & CSS','JavaScript','React','Git'],'featured'=>true],
