['id'=>103,'title'=>'UI/UX Design Intern','company'=>'Studio Ember','location'=>'Remote, India','type'=>'Internship','workplace'=>'Remote','salary'=>'₹12–18k / month','experience'=>'Fresher','category'=>'Design','logo'=>'S','color'=>'orange','posted'=>'3 days ago','description'=>'Collaborate with product and engineering to turn user needs into clear, thoughtful interfaces. You will contribute to research, wireframes, prototypes and design systems.','skills'=>['Figma','Wireframing','Prototyping','Design systems'],'featured'=>false],
['id'=>104,'title'=>'Customer Success Associate','company'=>'CloudHarbor','location'=>'Gandhinagar, Gujarat','type'=>'Full Time','workplace'=>'Hybrid','salary'=>'₹3.5–5 LPA','experience'=>'0–2 years','category'=>'Customer Support','logo'=>'C','color'=>'green','posted'=>'4 days ago','description'=>'Help customers get the most value from our platform. You will answer product questions, identify patterns in feedback and work with internal teams to improve the customer experience.','skills'=>['Communication','Problem solving','CRM'],'featured'=>false],
['id'=>105,'title'=>'Data Analyst','company'=>'MetricMint','location'=>'Remote, India','type'=>'Full Time','workplace'=>'Remote','salary'=>'₹4–7 LPA','experience'=>'1–2 years','category'=>'Data','logo'=>'M','color'=>'pink','posted'=>'5 days ago','description'=>'Turn business questions into useful analysis. Prepare datasets, build reports and communicate insights that help teams make confident decisions.','skills'=>['SQL','Excel','Power BI','Python'],'featured'=>true],
['id'=>106,'title'=>'Digital Marketing Executive','company'=>'BloomReach Media','location'=>'Ahmedabad, Gujarat','type'=>'Full Time','workplace'=>'On-site','salary'=>'₹3–4.5 LPA','experience'=>'1–3 years','category'=>'Marketing','logo'=>'B','color'=>'gold','posted'=>'6 days ago','description'=>'Plan and execute digital campaigns, monitor performance and support content strategy across search and social channels.','skills'=>['SEO','Analytics','Content','Campaigns'],'featured'=>false],
