function init_state(){if(!isset($_SESSION['jobs']))$_SESSION['jobs']=seed_jobs();if(!isset($_SESSION['applications']))$_SESSION['applications']=[];if(!isset($_SESSION['custom_users']))$_SESSION['custom_users']=[];if(!isset($_SESSION['posted_jobs']))$_SESSION['posted_jobs']=[];if(!isset($_SESSION['profile']))$_SESSION['profile']=[];if(!isset($_SESSION['prefs']))$_SESSION['prefs']=['relevant_jobs'=>true,'matches'=>true,'applications'=>true,'invitations'=>false];}
init_state();
function current_user(){return $_SESSION['user']??null;}
function flash($type,$message){$_SESSION['flashes'][]=['type'=>$type,'message'=>$message];}
function take_flashes(){$f=$_SESSION['flashes']??[];unset($_SESSION['flashes']);return $f;}
function active($p,$list){return in_array($p,$list,true)?'active':'';}
function handle_post($page){
  $action=$_POST['action']??'';
  if($action==='signin'){
    $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');
    if(!$email||strlen($pass)<1){flash('error','Enter a valid email and password.');redirect('signin');}
    $demo=[['email'=>'employee@demo.com','password'=>'Demo123!','role'=>'employee','name'=>'Harshal Lathiya'],['email'=>'employer@demo.com','password'=>'Demo123!','role'=>'employer','name'=>'Aarav Mehta']];$found=null;
    foreach($demo as $d)if(strtolower($d['email'])===strtolower($email)&&$d['password']===$pass)$found=$d;
    foreach($_SESSION['custom_users'] as $d)if(strtolower($d['email'])===strtolower($email)&&password_verify($pass,$d['password']))$found=$d;
    if(!$found){flash('error','We couldn’t match those details. Check your email and password, or create an account.');redirect('signin');}
    session_regenerate_id(true);$_SESSION['user']=['email'=>$found['email'],'role'=>$found['role'],'name'=>$found['name']];flash('success','Welcome back, '.$found['name'].'.');redirect($found['role']==='employer'?'employer-home':'home');
  }
  if($action==='signup'){
    $name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
    if(mb_strlen($name)<2||!$email||strlen($pass)<8||$pass!==$confirm){flash('error','Check your name, email, and password. Use at least 8 characters and make both passwords match.');redirect('signup');}
    foreach(array_merge($_SESSION['custom_users'],[['email'=>'employee@demo.com'],['email'=>'employer@demo.com']]) as $d)if(strtolower($d['email'])===strtolower($email)){flash('error','An account with that email already exists. Try signing in.');redirect('signup');}
    $_SESSION['pending_signup']=['name'=>$name,'email'=>$email,'password'=>password_hash($pass,PASSWORD_DEFAULT)];redirect('role');
  }
  if($action==='role'){
    $role=$_POST['role']??'';if(!in_array($role,['employee','employer'],true)){flash('error','Choose one account type to continue.');redirect('role');}
    if(isset($_SESSION['pending_signup'])){$d=$_SESSION['pending_signup'];$d['role']=$role;$_SESSION['custom_users'][]=$d;$_SESSION['user']=['name'=>$d['name'],'email'=>$d['email'],'role'=>$role];unset($_SESSION['pending_signup']);}
    elseif(current_user()){$_SESSION['user']['role']=$role;}else{flash('error','Start by creating an account first.');redirect('signup');}
    $_SESSION['onboarding_role']=$role;flash('success','Great choice. Let’s set up your '.($role==='employee'?'job seeker':'employer').' profile.');redirect($role==='employee'?'employee-onboarding':'employer-onboarding');
  }
  if($action==='onboarding'){
    $role=$_SESSION['onboarding_role']??current_user()['role']??'employee';$required=$role==='employee'?['name','age','location','nationality','qualification','experience','salary','employment_type','industry']:['company','location','industry','position','employment_type','salary','job_detail'];
    $data=[];foreach($_POST as $k=>$v)if(is_string($v))$data[$k]=trim($v);
    foreach($required as $r)if(empty($data[$r])){flash('error','Please complete all required fields before continuing.');redirect($role==='employee'?'employee-onboarding':'employer-onboarding');}
    $_SESSION['profile'][$current_user()['email']]=array_merge($_SESSION['profile'][$current_user()['email']]??[],$data,['completed'=>true]);$_SESSION['user']['name']=$role==='employee'?($data['name']??current_user()['name']):current_user()['name'];unset($_SESSION['onboarding_role']);flash('success','Your profile is ready. You can update these details any time.');redirect($role==='employee'?'home':'employer-home');
  }
  if($action==='apply'){$u=current_user();$id=(int)($_POST['job_id']??0);$exists=false;foreach($_SESSION['applications'] as $a)if($a['job_id']===$id&&$a['email']===$u['email'])$exists=true;if($exists){flash('error','You have already applied for this role.');redirect('jobs');}$job=null;foreach($_SESSION['jobs'] as $j)if($j['id']===$id)$job=$j;if(!$job){flash('error','This job is no longer available.');redirect('jobs');}$_SESSION['applications'][]=['job_id'=>$id,'email'=>$u['email'],'status'=>'Application received','date'=>date('M j, Y'),'job_title'=>$job['title'],'company'=>$job['company']];flash('success','Application submitted for '.$job['title'].'.');redirect('interviews');}
  if($action==='save_profile'){$u=current_user();$name=trim($_POST['name']??'');if(mb_strlen($name)<2){flash('error','Please enter your full name.');redirect('edit-profile');}$_SESSION['user']['name']=$name;$_SESSION['profile'][$u['email']]=array_merge($_SESSION['profile'][$u['email']]??[],array_map('trim',$_POST));flash('success','Your profile changes have been saved.');redirect('profile');}
  if($action==='save_prefs'){foreach(['relevant_jobs','matches','applications','invitations'] as $k)$_SESSION['prefs'][$k]=isset($_POST[$k]);flash('success','Your notification preferences are updated.');redirect('settings');}
  if($action==='post_job'){$required=['title','company','employment_type','experience','salary','location','job_type','workplace'];foreach($required as $k)if(trim($_POST[$k]??'')===''){flash('error','Please complete all required fields.');redirect('post-job');}$job=['id'=>random_int(2000,9999),'title'=>trim($_POST['title']),'company'=>trim($_POST['company']),'location'=>trim($_POST['location']),'type'=>trim($_POST['employment_type']),'workplace'=>trim($_POST['workplace']),'salary'=>trim($_POST['salary']),'experience'=>trim($_POST['experience']),'category'=>'Your jobs','logo'=>strtoupper(substr(trim($_POST['company']),0,1)),'color'=>'gold','posted'=>'Just now','description'=>trim($_POST['description']??'A new opportunity to join our team.'),'skills'=>array_values(array_filter(array_map('trim',explode(',',$_POST['skills']??'')))),'featured'=>false,'employer_email'=>current_user()['email']];array_unshift($_SESSION['jobs'],$job);$_SESSION['posted_jobs'][]=$job['id'];flash('success','Your job post is live in this demo workspace.');redirect('employer-home');}
}
function render_page($page,$user){$p=__DIR__.'/pages/'.$page.'.php';if(file_exists($p)){require $p;return;}require __DIR__.'/pages/welcome.php';}
function jobs_for_viewer(){return $_SESSION['jobs']??[];}
function find_job($id){foreach(jobs_for_viewer() as $j)if((int)$j['id']===(int)$id)return $j;return null;}
function has_applied($id){foreach($_SESSION['applications'] as $a)if($a['job_id']===(int)$id&&$a['email']===(current_user()['email']??''))return true;return false;}
function icon($name){$icons=['search'=>'⌕','bell'=>'♧','briefcase'=>'▣','pin'=>'⌖','clock'=>'◷','arrow'=>'↗','check'=>'✓','spark'=>'✦','users'=>'♙','chart'=>'▥','file'=>'▤','settings'=>'⚙'];return $icons[$name]??'•';}
function render_job_card($j,$compact=false){?><article class="job-card"><div class="job-card-top"><div class="company-logo logo-<?=e($j['color'])?>"><?=e($j['logo'])?></div><div class="job-main"><div class="job-company"><?=e($j['company'])?> <span class="verified">✓</span></div><h3><a href="<?=url('job-detail',['id'=>$j['id']])?>"><?=e($j['title'])?></a></h3></div><button class="bookmark" type="button" aria-label="Save job" data-bookmark>♡</button></div><div class="job-meta"><span>⌖ <?=e($j['location'])?></span><span>◷ <?=e($j['type'])?></span><span>▣ <?=e($j['workplace'])?></span></div><?php if(!$compact):?><p class="job-description"><?=e($j['description'])?></p><div class="skill-list"><?php foreach(array_slice($j['skills'],0,4) as $s):?><span><?=e($s)?></span><?php endforeach;?></div><?php endif;?><div class="job-card-bottom"><div><strong><?=e($j['salary'])?></strong><span class="posted"> · <?=e($j['posted'])?></span></div><a class="text-link" href="<?=url('job-detail',['id'=>$j['id']])?>">View details <span>↗</span></a></div></article><?php }
?>